// Normalise any incoming Telegram message into one clean object
const msg = $input.first().json.message || {};
const text = (msg.text || msg.caption || '').trim();
const chatId = msg.chat ? msg.chat.id : null;
const from = msg.from || {};
const reporter = [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'Unknown';
const photoFileId = Array.isArray(msg.photo) && msg.photo.length ? msg.photo[msg.photo.length - 1].file_id : '';

let route = 'complaint';
let ticketQuery = '';
if (/^\/(start|help)/i.test(text)) {
  route = 'help';
} else if (/^\/status/i.test(text)) {
  ticketQuery = text.replace(/^\/status\s*/i, '').trim().toUpperCase();
  route = /^PTH-\d{8}-\d{4}$/.test(ticketQuery) ? 'status' : 'help';
} else if (!text && photoFileId) {
  route = 'need_details';
} else if (text.length < 15) {
  route = 'need_details';
}
const detailMsg = (!text && photoFileId)
  ? 'Thanks for the photo. A description is required to file a complaint. Please send the photo again with a caption, or send a text message, describing the problem and its exact location (street, landmark, area, city).'
  : 'Your message is too short to file a complaint. Please describe the road problem and its exact location (street, landmark, area, city) in one message. A photo is optional. Send /help for an example.';

const systemPrompt = [
  'You are a municipal road-complaint intake assistant.',
  'Extract details from a citizen message about a road problem.',
  'Return ONLY a JSON object with these keys:',
  'is_pothole_report (boolean: true only if the message reports a road surface problem),',
  'description (string, cleaned-up description in plain English),',
  'location_text (string: street, landmark, area and city exactly as given; empty string if no location is given),',
  'severity (one of: low, medium, high),',
  'hazard_type (one of: pothole, waterlogged_pothole, open_manhole, road_cave_in, other),',
  'ai_summary (string, max 20 words),',
  'missing_info (array of strings describing what is missing, empty if nothing).',
  'Severity rules: high if the message mentions an accident, injury, a vehicle fall, an open manhole, a cave-in, or a location near a school or hospital;',
  'medium if it blocks or slows traffic or is large or deep; low otherwise.',
  'Never invent a location, landmark, or detail that is not in the message.',
  'Use only the text description. Do not assume anything about any photo.',
  'The message may be in English, Hindi, or Hinglish. Always answer in English.'
].join(' ');

return [{ json: {
  route,
  chat_id: chatId,
  reporter,
  text,
  ticket_query: ticketQuery,
  photo_file_id: photoFileId,
  has_photo: Boolean(photoFileId),
  detail_msg: detailMsg,
  ai_body: {
    model: 'gpt-4o-mini',
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: text }
    ]
  }
}}];

// Find the ticket and format a status reply
const q = $('Normalize Message').first().json.ticket_query;
const chatId = $('Normalize Message').first().json.chat_id;
const rows = $input.all().map(i => i.json).filter(r => String(r.ticket_id || '').toUpperCase() === q);

let text;
if (!rows.length) {
  text = 'No complaint found with ID ' + q + '. Please check the ID and try again.';
} else {
  const r = rows[rows.length - 1];
  text = 'Complaint ' + r.ticket_id + '\n'
    + 'Status: ' + (r.status || 'Open') + '\n'
    + 'Severity: ' + r.severity + '\n'
    + 'Location: ' + r.location_text + '\n'
    + 'Filed on: ' + r.created_at
    + (r.officer_note ? '\nOfficer note: ' + r.officer_note : '');
}
return [{ json: { chat_id: chatId, text } }];

// Parse the AI output, validate it, and build the ticket row
const src = $('Normalize Message').first().json;
let ai = {};
try {
  ai = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  ai = { is_pothole_report: false, missing_info: ['The message could not be understood'] };
}

const severity = ['low', 'medium', 'high'].includes(ai.severity) ? ai.severity : 'medium';
const hazards = ['pothole', 'waterlogged_pothole', 'open_manhole', 'road_cave_in', 'other'];
const hazardType = hazards.includes(ai.hazard_type) ? ai.hazard_type : 'other';
const locationText = String(ai.location_text || '').trim();

const reasons = [];
if (ai.is_pothole_report !== true) reasons.push('This does not look like a road or pothole complaint');
if (locationText.length < 3) reasons.push('Location is missing (street, landmark, area, city)');
if (Array.isArray(ai.missing_info)) {
  for (const m of ai.missing_info) if (m && !reasons.includes(m)) reasons.push(String(m));
}
const valid = ai.is_pothole_report === true && locationText.length >= 3;

// Ticket ID in Indian Standard Time: PTH-YYYYMMDD-NNNN
const now = new Date();
const ist = new Date(now.getTime() + 5.5 * 60 * 60 * 1000);
const ymd = ist.toISOString().slice(0, 10).replace(/-/g, '');
const ticketId = 'PTH-' + ymd + '-' + String(Math.floor(1000 + Math.random() * 9000));

return [{ json: {
  valid,
  reasons,
  row: {
    ticket_id: ticketId,
    created_at: now.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
    chat_id: String(src.chat_id),
    reporter: src.reporter,
    description: String(ai.description || src.text).slice(0, 500),
    location_text: locationText,
    maps_link: locationText ? 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(locationText) : '',
    severity,
    hazard_type: hazardType,
    ai_summary: String(ai.ai_summary || '').slice(0, 200),
    status: 'Open',
    photo_file_id: src.photo_file_id
  }
}}];

